import numpy as np
from scipy.spatial.distance import cdist
from scipy.spatial.transform import Rotation
from scipy.optimize import differential_evolution
lines=open('initial.xyz').readlines()[2:]
elems=[line.split()[0] for line in lines]
r=np.array([[float(x) for x in line.split()[1:]] for line in lines]);
groups=[range(1,35),range(35,47),range(47,59),range(59,71),range(71,74)]

radii={'H':1.12,'C':1.80,'N':1.63,'P':2.0,'Se':2.08}
# minimal thresholds H-H 2.2, C-H 2.9, C-C 3.5; Se-H 3.2; Se-C 3.7

def place(t):
 q=r.copy()
 for g,pivot,ax,theta in [(groups[0],1,r[1]-r[0],t[0]),(range(37,47),35,r[36]-r[35],t[1]),(range(49,59),47,r[48]-r[47],t[2]),(range(61,71),59,r[60]-r[59],t[3])]:
  if pivot==1:ids=np.array(list(g))[1:]
  else: ids=np.array(list(g))
  q[ids]=(q[ids]-r[pivot])@Rotation.from_rotvec(theta*ax/np.linalg.norm(ax)).as_matrix().T+r[pivot]
 return q

def score(t):
 q=place(t)
 energy=0
 for i in range(len(groups)):
  for j in range(i+1,len(groups)):
   ii=list(groups[i]);jj=list(groups[j]);d=cdist(q[ii],q[jj]); crit=np.array([[radii[elems[k]]+radii[elems[h]] for h in jj] for k in ii]); delta=np.minimum(d-crit,0);energy+=np.sum(delta**2)
 # Re to any carbon/h atoms (and N-C outside), suppress Re to coordinating ligand elements
 d=np.linalg.norm(q[1:],axis=1)
 for k in range(1,len(q)):
  if elems[k] in ['H','C']:
   energy+=max(3.2-d[k-1],0)**2
 return energy
res=differential_evolution(score,[(0,2*np.pi)]*4,popsize=18,maxiter=140,tol=1e-6,seed=31,polish=True)
print('result',res.fun, 'angles degree',np.rad2deg(res.x))
q=place(res.x)
for i in range(len(groups)):
 for j in range(i+1,len(groups)):
  I=list(groups[i]);J=list(groups[j]);d=cdist(q[I],q[J]);ix,iy=np.unravel_index(d.argmin(),d.shape);print(i,j,'minimum',round(d[ix,iy],2),I[ix],J[iy],elems[I[ix]],elems[J[iy]])
with open('answer.xyz','w') as f:
 f.write(f'{len(elems)}\nRe(SePh)3(PPh3)(HCN), five-coordinate, molecular geometry\n')
 for atom,p in zip(elems,q):f.write('%-2s %15.8f %15.8f %15.8f\n'%(atom,*p))
